573	  Effect.gen(function* testIncrementalEmission() {
574	    const request = yield* openAIRequest;
575	    const releaseUpstream = yield* Deferred.make<null>();
576	    const firstMappedChunk = yield* Deferred.make<null>();
577	    const source = streamBytes(
578	      'data: {"type":"response.output_text.delta","sequence_number":0,"output_index":0,"delta":"Early"}\n\n'
579	    ).pipe(
580	      Stream.concat(
581	        Stream.fromEffect(
582	          Deferred.await(releaseUpstream).pipe(
583	            Effect.as(
584	              new TextEncoder().encode(
585	                'data: {"type":"response.completed","sequence_number":1,"response":{"status":"completed"}}\n\n'
586	              )
587	            )
588	          )
589	        )
590	      )
591	    );
592	    const output = yield* toOpenAICompatibleStream({
593	      model: request.model,
594	      body: source,
595	    }).pipe(Effect.provide(CodexStreamMapperTest));
596	    let received = "";
597	    const fiber = yield* Effect.forkChild(
598	      output.body.pipe(
599	        Stream.decodeText(),
600	        Stream.runForEach((part) =>
601	          Effect.sync(() => {
602	            received += part;
603	          }).pipe(
604	            Effect.andThen(Deferred.succeed(firstMappedChunk, null)),
605	            Effect.asVoid
606	          )
607	        )
608	      )
609	    );
