const probe = await tools.exec_command({
  cmd:`bun --conditions=@bundjil/source --eval '
import { ConfigProvider, Effect, Layer, Schema } from "effect";
import { HttpClient, HttpClientResponse } from "effect/unstable/http";
import { CodexResponsesPostInput } from "./packages/codex/src/provider/contracts.ts";
import { CodexHttpClient, makeCodexHttpClient } from "./packages/codex/src/provider/http-client.ts";

let aborted = false;
const response = new Response("data: {\\"type\\":\\"response.completed\\",\\"sequence_number\\":0,\\"response\\":{\\"status\\":\\"completed\\"}}\\n\\n", {
  headers: { "content-type": "text/event-stream" },
  status: 200
});
const transport = HttpClient.make((request, _url, signal) =>
  Effect.sync(() => {
    signal.addEventListener("abort", () => { aborted = true; }, { once: true });
    return HttpClientResponse.fromWeb(request, response);
  })
);
const layer = Layer.effect(CodexHttpClient, makeCodexHttpClient).pipe(
  Layer.provide(Layer.merge(
    Layer.succeed(HttpClient.HttpClient, transport),
    ConfigProvider.layer(ConfigProvider.fromEnv({ env: {} }))
  ))
);
const program = Effect.gen(function* () {
  const input = yield* Schema.decodeUnknownEffect(CodexResponsesPostInput)({
    accessToken: "probe-access-token",
    request: {
      model: "gpt-5.5",
      input: [{ role: "user", content: [{ type: "input_text", text: "hello" }] }],
      store: false,
      stream: true
    }
  });
  const client = yield* CodexHttpClient;
  yield* client.postResponsesStream(input);
}).pipe(Effect.provide(layer));
await Effect.runPromise(program);
console.log("abort-after-discarded-success-stream=" + String(aborted));
console.log("body-used-after-discarded-success-stream=" + String(response.bodyUsed));
'`,
